<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Painel de controle · Integração BI</title>
    <style>
        :root{--bg:#07110f;--panel:#0d1c18;--panel2:#10231e;--line:#26483f;--muted:#8ba79f;--text:#edf7f3;--green:#5dd6ad;--amber:#f3bd65;--red:#ff887e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}.layout{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.sidebar{position:sticky;top:0;height:100vh;padding:26px 18px;border-right:1px solid #1e3932;background:#091713}.brand{display:flex;align-items:center;gap:11px;padding:0 8px 28px}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#16372e;color:var(--green)}.brand strong{display:block;font-size:14px}.brand small{color:var(--muted);font-size:10px;letter-spacing:.09em;text-transform:uppercase}.nav-label{padding:0 10px;margin:16px 0 7px;color:#5f8177;font-size:10px;text-transform:uppercase;letter-spacing:.13em}.nav-item{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:10px;color:#91aea5;text-decoration:none;font-size:13px}.nav-item.active{background:#153129;color:#eafff7}.nav-item:hover{color:#fff;background:#10251f}.sidebar-foot{position:absolute;left:18px;right:18px;bottom:20px}.who{padding:12px;border:1px solid #203d35;border-radius:12px;margin-bottom:9px;color:#a9c3bb;font-size:12px}.logout{width:100%;padding:10px;border:1px solid #2a4a41;border-radius:10px;background:transparent;color:#a9c3bb;cursor:pointer}.main{min-width:0;padding:34px clamp(22px,4vw,58px) 60px;background-image:radial-gradient(circle at 85% 0,#15382f 0,transparent 25%)}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:30px}h1{margin:0;font-size:28px;letter-spacing:-.045em}.subtitle{margin:7px 0 0;color:var(--muted);font-size:13px}.actions{display:flex;gap:10px}.button{padding:10px 14px;border:1px solid #31574c;border-radius:10px;background:#10231e;color:#d9ebe5;text-decoration:none;font-weight:650;font-size:12px;cursor:pointer}.button.primary{border-color:#4fbd98;background:var(--green);color:#062219}.button:disabled{opacity:.55}.cards{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:12px;margin-bottom:26px}.metric{padding:18px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(145deg,#10231e,#0b1916)}.metric span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;margin-top:9px;font-size:25px;letter-spacing:-.04em}.section{margin-top:24px}.section-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.section h2{margin:0;font-size:16px}.section-head p{margin:4px 0 0;color:var(--muted);font-size:12px}.connections{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.connection{padding:17px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}.connection-top{display:flex;justify-content:space-between}.status{display:inline-flex;align-items:center;gap:6px;font-size:11px}.dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}.offline .dot{background:var(--red)}.connection strong{font-size:14px}.connection dl{display:grid;grid-template-columns:1fr auto;gap:7px;margin:15px 0 0;color:var(--muted);font-size:11px}.connection dd{margin:0;color:#cce0da}.credentials{display:flex;gap:10px;overflow:auto;padding-bottom:4px}.credential{min-width:260px;padding:15px;border:1px solid var(--line);border-radius:13px;background:var(--panel)}.credential .code{font-weight:800}.credential .url{margin:6px 0;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#173c31;color:#7ce5bf;font-size:10px}.pill.off{background:#3a211e;color:#ffaaa2}.table-panel{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--panel)}.toolbar{display:flex;gap:10px;padding:13px;border-bottom:1px solid var(--line)}.search{flex:1;max-width:360px;padding:10px 12px;border:1px solid #2b5046;border-radius:9px;background:#081612;color:#fff;outline:none}.filter{padding:10px;border:1px solid #2b5046;border-radius:9px;background:#0b1a16;color:#bcd1cb}table{width:100%;border-collapse:collapse}th,td{padding:12px 15px;text-align:left;border-bottom:1px solid #19332c;font-size:12px}th{color:#789a90;font-size:10px;text-transform:uppercase;letter-spacing:.08em}tbody tr:hover{background:#10261f}td.name{color:#dff4ed;font-family:ui-monospace,SFMono-Regular,monospace}.empty{color:var(--amber)}.muted{color:var(--muted)}.footer-time{margin-top:12px;color:#607e75;font-size:11px;text-align:right}.modal-overlay{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:18px;background:#0000;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .22s ease,background-color .22s ease,visibility 0s linear .22s}.modal-overlay.open{background:#000a;opacity:1;visibility:visible;pointer-events:auto;transition-delay:0s}.modal{width:min(470px,100%);padding:21px;border:1px solid #31584d;border-radius:15px;background:#0d1c18;box-shadow:0 25px 80px #000;opacity:0;transform:translateY(14px) scale(.97);transition:opacity .22s ease,transform .22s cubic-bezier(.2,.8,.2,1)}.modal-overlay.open .modal{opacity:1;transform:translateY(0) scale(1)}.modal-head{display:flex;align-items:flex-start;justify-content:space-between}.modal h2{margin:0;font-size:17px}.modal p{color:var(--muted);font-size:11px;line-height:1.6}.modal-close{border:0;background:transparent;color:#9bb9b0;font-size:22px;cursor:pointer}.modal label{display:block;margin-top:12px;color:#9cb8b0;font-size:11px}.modal input{display:block;width:100%;margin-top:6px;padding:11px;border:1px solid #31584d;border-radius:9px;background:#081612;color:#fff}.form-error{margin-top:7px;color:#ffaaa2;font-size:11px}.flash{margin-bottom:14px;padding:11px 14px;border:1px solid #34715f;border-radius:10px;background:#123128;color:#8ce8c6;font-size:12px}.toast{position:fixed;right:22px;bottom:22px;padding:12px 15px;border:1px solid #39705f;border-radius:10px;background:#15342b;box-shadow:0 15px 40px #0008;font-size:12px;opacity:0;transform:translateY(10px);pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:none}@media(max-width:1050px){.cards{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.layout{display:block}.sidebar{position:static;width:100%;height:auto;border-right:0;border-bottom:1px solid var(--line)}.sidebar .nav-label,.sidebar .nav-item:not(.active),.sidebar-foot{display:none}.brand{padding-bottom:12px}.main{padding:25px 16px 50px}.top{display:block}.actions{margin-top:18px}.cards{grid-template-columns:repeat(2,1fr)}.connections{grid-template-columns:1fr}.table-panel{overflow:auto}table{min-width:680px}}
        .toolbar .button{margin-left:auto;white-space:nowrap}.sync-badge{display:inline-block;margin-left:8px;padding:3px 7px;border-radius:999px;background:#173c31;color:#7ce5bf;font:9px Inter,ui-sans-serif,system-ui,sans-serif;text-transform:uppercase;letter-spacing:.06em}
        .button.icon{width:38px;height:38px;padding:0;display:grid;place-items:center;border-radius:50%;font-size:20px;line-height:1}.button.icon.loading{animation:spin .8s linear infinite}.reload-button{padding:6px 9px;font-size:10px}.reload-state{display:block;margin-top:5px;color:var(--amber);font-size:9px;max-width:240px}.reload-state.failed{color:var(--red)}@keyframes spin{to{transform:rotate(360deg)}}
    </style>
</head>
<body><div class="layout">
    <aside class="sidebar"><div class="brand"><div class="mark">◆</div><div><strong>Integração BI</strong></div></div><div class="nav-label">Visão geral</div><a class="nav-item active" href="{{ route('admin.dashboard') }}">◫ &nbsp; Painel</a><a class="nav-item" href="{{ route('admin.financial') }}">▥ &nbsp; Financeiro</a><a class="nav-item" href="{{ route('admin.services') }}">◇ &nbsp; Serviços</a><a class="nav-item" href="{{ route('docs') }}" target="_blank">↗ &nbsp; Swagger API</a><div class="sidebar-foot"><form method="POST" action="{{ route('admin.logout') }}">@csrf<button class="logout">Encerrar sessão</button></form></div></aside>
    <main class="main">@if(session('status'))<div class="flash">{{ session('status') }}</div>@endif<header class="top" style="justify-content:flex-end"><div class="actions"><button class="button primary icon" id="refresh" title="Atualizar" aria-label="Atualizar">↻</button></div></header>
        <section class="cards" id="metrics"><div class="metric"><span>Empresas</span><strong data-metric="companies">{{ $overview['summary']['companies'] }}</strong></div><div class="metric"><span>Credenciais</span><strong data-metric="credentials">{{ $overview['summary']['credentials'] }}</strong></div><div class="metric"><span>Credenciais ativas</span><strong data-metric="active_credentials">{{ $overview['summary']['active_credentials'] }}</strong></div><div class="metric"><span>Tabelas WebPosto</span><strong data-metric="tables">{{ $overview['summary']['tables'] }}</strong></div><div class="metric"><span>Tokens da API</span><strong data-metric="api_tokens">{{ $overview['summary']['api_tokens'] }}</strong></div></section>
        <section class="section"><div class="section-head"><div><h2>Conexões</h2></div></div><div class="connections" id="connections"></div></section>
        <section class="section"><div class="section-head"><div><h2>Credenciais do WebPosto</h2><p>Empresas identificadas pelos tokens cadastrados.</p></div><button class="button primary icon" id="add-credential" type="button" title="Cadastrar token" aria-label="Cadastrar token">+</button></div><div class="credentials" id="credentials"></div></section>
        <section class="section"><div class="section-head"><div><h2>Inventário do banco WebPosto</h2><p>Quantidade, colunas, tamanho e última atualização de cada tabela.</p></div></div><div class="table-panel"><div class="toolbar"><input class="search" id="search" placeholder="Buscar tabela..."><select class="filter" id="filter"><option value="all">Todas</option><option value="modified-sync">Service por altera&ccedil;&atilde;o</option><option value="reloadable">Cargas validadas</option><option value="filled">Com dados</option><option value="empty">Vazias</option></select><select class="filter" id="reload-company" aria-label="Empresa para recarga"></select><button class="button" id="refresh-tables" type="button">&#8635; Atualizar tabelas</button></div><table><thead><tr><th>Tabela</th><th>Registros</th><th>Colunas</th><th>Tamanho</th><th>Última atualização</th><th>Ações</th></tr></thead><tbody id="table-body"></tbody></table></div><div class="footer-time">Atualizado em <span id="generated-at"></span></div></section>
    </main></div><div class="modal-overlay" id="reload-modal"><div class="modal"><div class="modal-head"><div><h2>Confirmar rebase</h2><p id="reload-modal-message"></p></div><button class="modal-close" id="reload-modal-close" type="button">&times;</button></div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:20px"><button class="button" id="reload-cancel" type="button">Não, cancelar</button><button class="button primary" id="reload-confirm" type="button">Sim, fazer rebase</button></div></div></div><div class="modal-overlay {{ $errors->any() ? 'open' : '' }}" id="credential-modal"><div class="modal"><div class="modal-head"><div><h2>Cadastrar credencial</h2><p>Cole o token; o WebPosto informar&aacute; qual empresa deve ser cadastrada.</p></div><button class="modal-close" id="credential-close" type="button">&times;</button></div><form method="POST" action="{{ route('admin.credentials.store') }}">@csrf<label>URL do WebPosto<input type="url" name="base_url" required value="{{ old('base_url','https://web.qualityautomacao.com.br/') }}"></label>@error('base_url')<div class="form-error">{{ $message }}</div>@enderror<label>Token<input type="password" name="token" required autocomplete="new-password" placeholder="Token fornecido pelo WebPosto"></label>@error('token')<div class="form-error">{{ $message }}</div>@enderror<button class="button primary" type="submit">Validar e cadastrar</button></form><p>O token ser&aacute; armazenado com criptografia e nunca ser&aacute; exibido no painel.</p></div></div><div class="toast" id="toast">Painel atualizado com sucesso.</div>
<script>
const initial=@json($overview);let state=initial;const fmt=new Intl.NumberFormat('pt-BR');const date=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v.replace(' ','T'))):'—';const bytes=v=>v<1024?v+' B':v<1048576?(v/1024).toFixed(1)+' KB':(v/1048576).toFixed(1)+' MB';
function render(data){state=data;Object.entries(data.summary).forEach(([k,v])=>{const e=document.querySelector(`[data-metric="${k}"]`);if(e)e.textContent=fmt.format(v)});document.getElementById('connections').innerHTML=data.connections.map(c=>`<article class="connection ${c.status==='offline'?'offline':''}"><div class="connection-top"><strong>${c.label}</strong><span class="status"><i class="dot"></i>${c.status==='online'?'Online':'Offline'}</span></div><dl><dt>Banco</dt><dd>${c.database??'—'}</dd><dt>Latência</dt><dd>${c.latency_ms===null?'—':c.latency_ms+' ms'}</dd></dl></article>`).join('');document.getElementById('credentials').innerHTML=data.credentials.length?data.credentials.map(c=>`<article class="credential"><div><span class="code">${c.empresa_nome}</span> <span class="pill ${c.active?'':'off'}">${c.active?'Ativa':'Inativa'}</span></div><p class="url">Código ${c.empresa_codigo}</p><span class="muted">Último uso: ${date(c.last_used)}</span></article>`).join(''):'<span class="muted">Nenhuma credencial cadastrada.</span>';document.getElementById('generated-at').textContent=date(data.generated_at);renderTables()}
const reloadUrl=@json(route('admin.tables.reload',['table'=>'__table__']));const csrf=@json(csrf_token());const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function renderTables(){const company=document.getElementById('reload-company');const previous=company.value;company.innerHTML=state.credentials.filter(c=>c.active).map(c=>`<option value="${c.empresa_codigo}">${esc(c.empresa_nome)} · ${c.empresa_codigo}</option>`).join('')||'<option value="">Sem credencial ativa</option>';if(previous&&[...company.options].some(o=>o.value===previous))company.value=previous;const empresa=Number(company.value);const q=document.getElementById('search').value.toLowerCase();const f=document.getElementById('filter').value;const rows=state.tables.filter(t=>t.name.toLowerCase().includes(q)&&(f==='all'||(f==='modified-sync'?t.modified_sync:(f==='reloadable'?['venda_itens','abastecimentos','bombas','bicos'].includes(t.name):(f==='empty'?t.records===0:t.records>0)))));document.getElementById('table-body').innerHTML=rows.map(t=>{const allowed=['venda_itens','abastecimentos','bombas','bicos'].includes(t.name);const run=(state.reloads||[]).find(r=>r.empresa_codigo===empresa&&r.resource===t.name);const busy=run&&['queued','running'].includes(run.status);const labels={queued:'Aguardando',running:'Executando',success:'Concluída',failed:'Falhou'};const action=allowed?`<form method="POST" action="${reloadUrl.replace('__table__',t.name)}" data-reload="${t.name}"><input type="hidden" name="_token" value="${csrf}"><input type="hidden" name="empresa_codigo" value="${empresa}"><button class="button reload-button" type="submit" ${busy||!empresa?'disabled':''}>${busy?'Recarga em andamento':'Recarregar dados'}</button>${run?`<span class="reload-state ${run.status==='failed'?'failed':''}">${labels[run.status]||run.status} · ${date(run.finished_at||run.started_at)}${run.error?' · '+esc(run.error):''}</span>`:''}</form>`:'—';return `<tr><td class="name">${t.name}${allowed?'<span class="sync-badge">Carga validada</span>':''}${t.modified_sync?'<span class="sync-badge">Por altera&ccedil;&atilde;o</span>':''}</td><td class="${t.records===0?'empty':''}">${fmt.format(t.records)}</td><td>${fmt.format(t.columns)}</td><td>${bytes(t.size_bytes)}</td><td class="muted">${date(t.last_update)}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Nenhuma tabela encontrada.</td></tr>'}
document.getElementById('search').addEventListener('input',renderTables);document.getElementById('filter').addEventListener('change',renderTables);document.getElementById('refresh').addEventListener('click',async function(){this.disabled=true;this.classList.add('loading');try{const r=await fetch(@json(route('admin.overview')),{headers:{Accept:'application/json'}});if(!r.ok)throw new Error();render(await r.json());const t=document.getElementById('toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}catch(e){alert('Não foi possível atualizar o painel. Verifique sua sessão e as conexões.')}finally{this.disabled=false;this.classList.remove('loading')}});document.getElementById('refresh-tables').addEventListener('click',function(){document.getElementById('refresh').click()});render(initial);
document.getElementById('reload-company').addEventListener('change',renderTables);const reloadModal=document.getElementById('reload-modal'),reloadMessage=document.getElementById('reload-modal-message'),reloadConfirm=document.getElementById('reload-confirm');let pendingReload=null;const closeReload=()=>{reloadModal.classList.remove('open');pendingReload=null;reloadConfirm.disabled=false};document.getElementById('table-body').addEventListener('submit',e=>{const form=e.target.closest('[data-reload]');if(!form)return;e.preventDefault();const table=form.dataset.reload,company=document.getElementById('reload-company').selectedOptions[0]?.textContent||'empresa selecionada';const effects={venda_itens:'venda_itens e abastecimentos',abastecimentos:'abastecimentos',bombas:'bombas e bicos',bicos:'bicos'};reloadMessage.textContent='Esta operação removerá os registros atuais e reconstruirá '+(effects[table]||table)+' para '+company+'. Deseja realmente continuar?';pendingReload=form;reloadModal.classList.add('open')});document.getElementById('reload-cancel').onclick=closeReload;document.getElementById('reload-modal-close').onclick=closeReload;reloadModal.addEventListener('click',e=>{if(e.target===reloadModal)closeReload()});reloadConfirm.onclick=()=>{if(!pendingReload)return;reloadConfirm.disabled=true;reloadConfirm.textContent='Enviando...';pendingReload.submit()};const credentialModal=document.getElementById('credential-modal');const closeCredential=()=>credentialModal.classList.remove('open');document.getElementById('add-credential').onclick=()=>credentialModal.classList.add('open');document.getElementById('credential-close').onclick=closeCredential;credentialModal.addEventListener('click',e=>{if(e.target===credentialModal)closeCredential()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCredential()});
</script></body></html>
